import re

# Let me extract the data systematically from all bulletins
# For each issue date, I need to find the amount outstanding

files = {
    "1970_01": "/app/resources/treasury_bulletin_1970_01.txt",  # Jan 1970
    "1970_02": "/app/resources/treasury_bulletin_1970_02.txt",  # Feb 1970
    "1970_03": "/app/resources/treasury_bulletin_1970_03.txt",  # Mar 1970
    "1970_04": "/app/resources/treasury_bulletin_1970_04.txt",  # Apr 1970
    "1970_05": "/app/resources/treasury_bulletin_1970_05.txt",  # May 1970
}

# Target issue dates (13-week bills)
target_dates = ["12/26/69", "1/29/70", "2/26/70", "3/26/70", "4/30/70"]

# Read each file and find the amounts
results = {}

for name, filepath in files:
    with open(filepath, 'r') as f:
        content = f.read()

    lines = content.split('\n')
    in_table = False

    for line in lines:
        if "Table MQ-1" in line:
            in_table = True
        if in_table:
            # Check if line starts with | and contains numbers (data row)
            if re.match(r'^\|\s*\$?\d', line) or re.match(r'^\|\s*\d', line):
                # Parse the line - format is | amount13week | amount26week | issue_date_13week | ...
                parts = [p.strip() for p in line.split('|')]
                # parts[1] = 13-week amount, parts[3] = issue date for 13-week
                if len(parts) > 4:
                    amount_13 = parts[1].replace('$', '').replace(',', '')
                    issue_date = parts[3]

                    if issue_date in target_dates:
                        try:
                            amt = float(amount_13)
                            results[issue_date] = amt
                            print(f"{name}: Issue date {issue_date} -> Amount ${amt} million")
                        except:
                            pass
        if 'Table MQ-2' in line:
            in_table = False

print("\n=== Summary ===")
for date, amt in sorted(results.items()):
    print(f"Issue date {date}: ${amt} million")
